package com.andye.warmod.phalanx.network;import com.andye.warmod.WarMod;import java.util.UUID;import net.minecraft.network.RegistryFriendlyByteBuf;import net.minecraft.network.codec.StreamCodec;import net.minecraft.network.protocol.common.custom.CustomPacketPayload;import net.minecraft.resources.Identifier;import net.minecraft.world.phys.Vec3;
public record ClientboundPhalanxShotPayload(UUID shotId,UUID turretId,UUID targetId,Vec3 origin,Vec3 velocity,long visualSeed)implements CustomPacketPayload{public static final Type<ClientboundPhalanxShotPayload> TYPE=new Type<>(Identifier.fromNamespaceAndPath(WarMod.MOD_ID,"phalanx_shot"));public static final StreamCodec<RegistryFriendlyByteBuf,ClientboundPhalanxShotPayload> STREAM_CODEC=StreamCodec.of((b,p)->{b.writeUUID(p.shotId);b.writeUUID(p.turretId);b.writeUUID(p.targetId);vec(b,p.origin);vec(b,p.velocity);b.writeLong(p.visualSeed);},b->new ClientboundPhalanxShotPayload(b.readUUID(),b.readUUID(),b.readUUID(),vec(b),vec(b),b.readLong()));private static void vec(RegistryFriendlyByteBuf b,Vec3 v){b.writeDouble(v.x);b.writeDouble(v.y);b.writeDouble(v.z);}private static Vec3 vec(RegistryFriendlyByteBuf b){return new Vec3(b.readDouble(),b.readDouble(),b.readDouble());}@Override public Type<? extends CustomPacketPayload> type(){return TYPE;}}
